import { CatalystAuthenticationError } from '../utils/error.js';
const BTN_ID = 'zc-signin-button';
export function showIframeConfirmModal(onConfirm, containerId, buttonLabel) {
    if (document.getElementById(BTN_ID)) {
        document.getElementById(BTN_ID)?.focus();
        return Promise.reject(new CatalystAuthenticationError('POPUP_ALREADY_OPEN', 'An authentication button is already rendered.'));
    }
    return new Promise((resolve, reject) => {
        const container = (containerId ? document.getElementById(containerId) : null) ?? document.body;
        const btn = document.createElement('button');
        btn.id = BTN_ID;
        btn.type = 'button';
        btn.textContent = buttonLabel ?? 'Sign In';
        btn.addEventListener('click', async () => {
            btn.disabled = true;
            try {
                await onConfirm();
                btn.remove();
                resolve();
            }
            catch (err) {
                btn.disabled = false;
                reject(err);
            }
        });
        container.appendChild(btn);
    });
}
